// build.zig
const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{ .preferred_optimize_mode = .ReleaseSafe });

    const exe = b.addExecutable(.{
        .name = "jaide",
        .root_source_file = .{ .path = "src/main.zig" },
        .target = target,
        .optimize = optimize,
    });

    // Core libs
    const core_types = b.addObject(.{
        .name = "core_types",
        .root_source_file = .{ .path = "src/core/types.zig" },
        .target = target,
        .optimize = optimize,
    });
    exe.addObject(core_types);

    const core_tensor = b.addObject(.{
        .name = "core_tensor",
        .root_source_file = .{ .path = "src/core/tensor.zig" },
        .target = target,
        .optimize = optimize,
    });
    exe.addObject(core_tensor);

    const rsf = b.addObject(.{
        .name = "processor_rsf",
        .root_source_file = .{ .path = "src/processor/rsf.zig" },
        .target = target,
        .optimize = optimize,
    });
    exe.addObject(rsf);

    // Link Futhark-generated C library if exists
    const out_dir = "out/gen";
    const futhark_c = std.fs.path.join(b.allocator, &.{ out_dir, "gpu_kernels.c" }) catch unreachable;
    const futhark_h = std.fs.path.join(b.allocator, &.{ out_dir, "gpu_kernels.h" }) catch unreachable;
    const have_futhark = fileExists(b, futhark_c) and fileExists(b, futhark_h);
    if (have_futhark) {
        const cobj = b.addCSourceFile(.{
            .file = .{ .path = futhark_c },
            .flags = &[_][]const u8{"-O3"},
        });
        exe.addObject(cobj);
    }

    exe.install();

    const run = b.addRunArtifact(exe);
    if (b.args) |args| run.addArgs(args);

    const unit_tests = b.addTest(.{
        .root_source_file = .{ .path = "src/processor/rsf.zig" },
        .target = target,
        .optimize = optimize,
    });

    const test_step = b.step("test", "Run all tests and verifications");
    const run_tests = b.addRunArtifact(unit_tests);

    // Verification hooks (shell out to flake-provided tools)
    const verify_step = b.step("verify", "Run formal verification suite");

    const run_lean = b.addSystemCommand(&[_][]const u8{
        "sh","-c","cd verification/lean && (lake build || true) && lean --make RSF_Invertibility.lean",
    });
    verify_step.dependOn(&run_lean.step);

    const run_isabelle = b.addSystemCommand(&[_][]const u8{
        "sh","-c","cd verification/isabelle && isabelle build -D . -v",
    });
    verify_step.dependOn(&run_isabelle.step);

    const run_tlc = b.addSystemCommand(&[_][]const u8{
        "sh","-c","cd verification/tla && tlc -deadlock -workers 2 Full_Pipeline_Liveness.tla || true",
    });
    verify_step.dependOn(&run_tlc.step);

    const run_circom = b.addSystemCommand(&[_][]const u8{
        "sh","-c","circom verification/zk/rsf_layer_proof.circom --inspect || true",
    });
    verify_step.dependOn(&run_circom.step);

    test_step.dependOn(&run_tests.step);
    test_step.dependOn(verify_step);

    b.default_step.dependOn(&exe.step);
}

fn fileExists(b: *std.Build, path: []const u8) bool {
    var fs = std.fs.cwd();
    return fs.access(path, .{}) == .success;
}
