// src/core/types.zig
const std = @import("std");

pub const CacheAlign = 64;

pub fn FixedPoint(comptime I: type, comptime F: type) type {
    return packed struct {
        // Qm.n fixed point, where I is signed integer storage, F is unsigned fractional storage bits
        raw: I,

        pub inline fn fromFloat(x: f64) @This() {
            const frac_bits = @bitSizeOf(F);
            const scale: f64 = @floatFromInt(@as(u64, 1) << @as(u6, @intCast(frac_bits)));
            const r = @as(I, @intFromFloat(x * scale));
            return .{ .raw = r };
        }

        pub inline fn toFloat(self: @This()) f64 {
            const frac_bits = @bitSizeOf(F);
            const scale: f64 = @floatFromInt(@as(u64, 1) << @as(u6, @intCast(frac_bits)));
            return @as(f64, @floatFromInt(self.raw)) / scale;
        }

        pub inline fn add(a: @This(), b: @This()) @This() {
            return .{ .raw = a.raw + b.raw };
        }

        pub inline fn sub(a: @This(), b: @This()) @This() {
            return .{ .raw = a.raw - b.raw };
        }

        pub inline fn mul(a: @This(), b: @This()) @This() {
            // widen to avoid overflow
            const W = i128;
            const frac_bits = @bitSizeOf(F);
            const prod: W = @as(W, a.raw) * @as(W, b.raw);
            const scaled: W = prod >> @as(u7, @intCast(frac_bits));
            return .{ .raw = @as(I, @intCast(scaled)) };
        }
    };
}

pub fn Tensor(comptime T: type, comptime order: usize) type {
    return struct {
        const Self = @This();
        shape: [order]usize,
        strides: [order]usize,
        data: []T,
        allocator: std.mem.Allocator,

        pub fn init(allocator: std.mem.Allocator, shape: [order]usize) !Self {
            var total: usize = 1;
            var strides: [order]usize = undefined;
            // row-major
            var i: isize = order - 1;
            var stride: usize = 1;
            while (i >= 0) : (i -= 1) {
                const ui = @as(usize, @intCast(i));
                strides[ui] = stride;
                stride *= shape[ui];
                total *= shape[ui];
            }
            const data = try allocator.alloc(T, total);
            return .{ .shape = shape, .strides = strides, .data = data, .allocator = allocator };
        }

        pub fn deinit(self: *Self) void {
            if (self.data.len != 0) self.allocator.free(self.data);
            self.* = undefined;
        }

        pub inline fn index(self: *const Self, idx: [order]usize) usize {
            var flat: usize = 0;
            var i: usize = 0;
            while (i < order) : (i += 1) {
                flat += idx[i] * self.strides[i];
            }
            return flat;
        }

        pub inline fn at(self: *const Self, idx: [order]usize) *const T {
            return &self.data[self.index(idx)];
        }

        pub inline fn atMut(self: *Self, idx: [order]usize) *T {
            return &self.data[self.index(idx)];
        }

        pub fn fill(self: *Self, value: T) void {
            for (self.data) |*p| p.* = value;
        }
    };
}

pub const RankedSegment = packed struct {
    hash: u128 align(CacheAlign),
    file_offset: u64,
    token_count: u32,
    score: f32,
};

pub const ContextWindow = packed struct {
    base_offset: u64,
    span_tokens: u64,
    segment_count: u32,
    reserved: u32,
};

pub const MorphemeNode = packed struct {
    // compressed radix node
    label_prefix_len: u8,
    label_prefix_bytes: [15]u8, // small inline storage for radix edge
    first_child: u32,
    sibling: u32,
    token_id: u32, // 0xFFFF_FFFF if non-terminal
    flags: u16,    // bits: anchor, unknown, dynamic
    freq: u16,
};
