// src/processor/rsf.zig
const std = @import("std");

pub const GeLU = struct {
    pub inline fn apply(x: f32) f32 {
        // Approximate GeLU
        const k: f32 = 0.044715;
        const s: f32 = 0.7978845608; // sqrt(2/pi)
        const x3 = x * x * x;
        const inner = s * (x + k * x3);
        return 0.5 * x * (1.0 + tanh(inner));
    }
};

pub fn Linear(comptime In: usize, comptime Out: usize) type {
    return struct {
        const Self = @This();
        w: [Out][In]f32,
        b: [Out]f32,

        pub fn init(rng: *std.rand.DefaultPrng) Self {
            var s = Self{
                .w = undefined,
                .b = undefined,
            };
            var i: usize = 0;
            while (i < Out) : (i += 1) {
                var j: usize = 0;
                s.b[i] = 0.0;
                while (j < In) : (j += 1) {
                    s.w[i][j] = (rng.random().float(f32) - 0.5) * 0.02;
                }
            }
            return s;
        }

        pub inline fn forward(self: *const Self, x: *const [In]f32) [Out]f32 {
            var y: [Out]f32 = undefined;
            var i: usize = 0;
            while (i < Out) : (i += 1) {
                var acc: f32 = self.b[i];
                var j: usize = 0;
                while (j < In) : (j += 1) {
                    acc += self.w[i][j] * x[j];
                }
                y[i] = acc;
            }
            return y;
        }
    };
}

pub fn RSFLayer(comptime D: usize, comptime H: usize) type {
    return struct {
        const Self = @This();
        // Split: x = [x1|x2], size D = 2H
        t1: @TypeOf(Linear(H, H).init),
        t2: @TypeOf(Linear(H, H).init),

        pub fn init(rng: *std.rand.DefaultPrng) Self {
            return .{
                .t1 = Linear(H, H).init(rng),
                .t2 = Linear(H, H).init(rng),
            };
        }

        fn trans(self: *const Self, x: *const [H]f32) [H]f32 {
            var h = self.t1.forward(x);
            var i: usize = 0;
            while (i < H) : (i += 1) h[i] = GeLU.apply(h[i]);
            return self.t2.forward(&h);
        }

        pub fn forward(self: *const Self, x: *const [D]f32) [D]f32 {
            comptime std.debug.assert(D == 2 * H);
            var y: [D]f32 = undefined;
            // y1 = x1
            var i: usize = 0;
            while (i < H) : (i += 1) y[i] = x[i];
            // y2 = x2 + t(x1)
            const tx = self.trans(@ptrCast(&x[0]));
            i = 0;
            while (i < H) : (i += 1) y[H + i] = x[H + i] + tx[i];
            return y;
        }

        pub fn backward(self: *const Self, y: *const [D]f32) [D]f32 {
            comptime std.debug.assert(D == 2 * H);
            var x: [D]f32 = undefined;
            // x1 = y1
            var i: usize = 0;
            while (i < H) : (i += 1) x[i] = y[i];
            // x2 = y2 - t(y1)
            const ty = self.trans(@ptrCast(&y[0]));
            i = 0;
            while (i < H) : (i += 1) x[H + i] = y[H + i] - ty[i];
            return x;
        }
    };
}

test "RSF forward/backward invertibility" {
    var prng = std.rand.DefaultPrng.init(0xC0FFEE);
    var rng = prng.random();
    const D = 8;
    const H = 4;
    var layer = RSFLayer(D, H).init(&prng);

    var x: [D]f32 = .{ 0 } ** D;
    for (x, 0..) |*v, i| v.* = @floatFromInt(@as(i32, @intCast((i * 7 + 3) % 11))) * 0.1;

    const y = layer.forward(&x);
    const xr = layer.backward(&y);

    var max_err: f32 = 0;
    for (x, 0..) |v, i| {
        const e = @abs(v - xr[i]);
        if (e > max_err) max_err = e;
    }
    try std.testing.expect(max_err < 1e-4);
}
