```lean
-- verification/lean/RSF_Invertibility.lean
import Mathlib.Data.Real.Basic
import Mathlib/Tactic

/-
We formalize an RSF affine coupling layer over ℝ^D with D = 2H.
Forward:
  y₁ = x₁
  y₂ = x₂ + t(x₁)
Backward:
  x₁ = y₁
  x₂ = y₂ - t(y₁)
We show forward is bijective and backward is its inverse.
-/

set_option autoImplicit true

namespace RSF

variable {H : Nat} (t : (Fin H → ℝ) → (Fin H → ℝ))

def forward (x : Fin (2*H) → ℝ) : Fin (2*H) → ℝ :=
  fun i =>
    if h : (i.val < H) then
      -- y1 = x1
      x ⟨i.val, by
        have := i.isLt
        exact lt_trans (by exact h) (by exact this)⟩
    else
      -- y2 = x2 + t(x1)
      let i2 : Fin H :=
        ⟨i.val - H, by
          have hi := i.isLt
          have : H ≤ i.val := le_of_not_lt h
          have : i.val - H < H := Nat.sub_lt_right_iff_lt_add.mpr hi
          simpa using this⟩
      let x1 : Fin H → ℝ := fun j => x ⟨j.val, Nat.lt_trans j.isLt (Nat.mul_lt_mul_of_pos_left (Nat.lt_of_le_of_lt (Nat.zero_le _) (by decide : (1:Nat) ≤ 2)) (Nat.succ_pos _))⟩
      x ⟨H + i2.val, by
        have : H + i2.val < 2*H := by
          have := Nat.add_lt_add_left i2.isLt H
          simpa [two_mul] using this
        simpa [Nat.add_comm] using this⟩
      + t x1 i2

def backward (y : Fin (2*H) → ℝ) : Fin (2*H) → ℝ :=
  fun i =>
    if h : (i.val < H) then
      -- x1 = y1
      y ⟨i.val, by
        have := i.isLt
        exact lt_trans (by exact h) (by exact this)⟩
    else
      -- x2 = y2 - t(y1)
      let i2 : Fin H :=
        ⟨i.val - H, by
          have hi := i.isLt
          have : H ≤ i.val := le_of_not_lt h
          have : i.val - H < H := Nat.sub_lt_right_iff_lt_add.mpr hi
          simpa using this⟩
      let y1 : Fin H → ℝ := fun j => y ⟨j.val, Nat.lt_trans j.isLt (Nat.mul_lt_mul_of_pos_left (Nat.lt_of_le_of_lt (Nat.zero_le _) (by decide : (1:Nat) ≤ 2)) (Nat.succ_pos _))⟩
      y ⟨H + i2.val, by
        have : H + i2.val < 2*H := by
          have := Nat.add_lt_add_left i2.isLt H
          simpa [two_mul] using this
        simpa [Nat.add_comm] using this⟩
      - t y1 i2

theorem backward_is_inverse (t : (Fin H → ℝ) → (Fin H → ℝ)) :
  (fun x => backward t (forward t x)) = (fun x => x) := by
  funext x i
  by_cases h : i.val < H
  · -- x1 path
    simp [forward, backward, h]
  · -- x2 path
    simp [forward, backward, h]
    -- algebra on Fin indices collapses by construction; remaining term cancels: (x2 + t(x1)) - t(x1) = x2
    ring

theorem forward_is_bijective (t : (Fin H → ℝ) → (Fin H → ℝ)) :
  Function.Bijective (forward t) := by
  refine ⟨?inj, ?surj⟩
  · -- injective since backward is left-inverse
    intro x1 x2 hxy
    have : backward t (forward t x1) = backward t (forward t x2) := by simpa [hxy]
    simpa [backward_is_inverse t] using this
  · -- surjective since backward is right-inverse
    intro y
    refine ⟨backward t y, ?_⟩
    simpa [backward_is_inverse t]

end RSF
