### Megjegyzés
- A további források (index/ssi.zig, ranker, tokenizer, optimizer, runtime ABI, IPC, scheduler, HW, TLA+, Isabelle teljes bizonyítás, Circom részletes áramkör) a következő iterációban adhatók hozzá az itt biztosított hermetikus buildkörnyezetre és RSF magra építve, változtatás nélkül illeszthető struktúrában.[1]

```zig
// src/core/memory.zig
const std = @import("std");
const os = std.posix;

pub const KiB = 1024;
pub const MiB = 1024 * KiB;
pub const GiB = 1024 * MiB;

pub const PageSize = 4096;
pub const DefaultArenaSize = 256 * MiB;
pub const GlobalArenaSize = 8 * GiB;

pub const RegionFlags = packed struct {
    read: bool = true,
    write: bool = true,
    exec: bool = false,
    shared: bool = false,
    locked: bool = false,
};

pub const Region = struct {
    base: [*]u8,
    len: usize,
    used: usize,
    flags: RegionFlags,

    pub fn available(self: *const Region) usize {
        return if (self.len > self.used) self.len - self.used else 0;
    }
};

pub const Arena = struct {
    region: Region,

    pub fn init(len: usize, flags: RegionFlags) !Arena {
        const prot: os.PROT = .{ .READ = flags.read, .WRITE = flags.write, .EXEC = flags.exec };
        const map_flags: os.MAP = .{
            .PRIVATE = !flags.shared,
            .SHARED = flags.shared,
            .ANONYMOUS = true,
            .STACK = false,
            .FIXED = false,
            .GROWSDOWN = false,
            .LOCKED = flags.locked,
        };
        const addr = try os.mmap(null, len, prot, map_flags, -1, 0);
        return .{
            .region = .{
                .base = @ptrCast(addr),
                .len = len,
                .used = 0,
                .flags = flags,
            },
        };
    }

    pub fn deinit(self: *Arena) void {
        if (self.region.len > 0) {
            _ = os.munmap(@ptrCast(self.region.base), self.region.len);
        }
        self.* = undefined;
    }

    pub fn alloc(self: *Arena, n: usize, align: usize) ![]u8 {
        const a = std.mem.alignForward(self.region.base + self.region.used, align);
        const new_used = (@intFromPtr(a) - @intFromPtr(self.region.base)) + n;
        if (new_used > self.region.len) return error.OutOfMemory;
        self.region.used = new_used;
        return a[0..n];
    }

    pub fn allocTyped(self: *Arena, comptime T: type, count: usize) ![]T {
        const bytes = try self.alloc(@sizeOf(T) * count, @alignOf(T));
        return std.mem.bytesAsSlice(T, bytes);
    }

    pub fn reset(self: *Arena) void {
        self.region.used = 0;
    }

    pub fn snapshot(self: *const Arena) usize {
        return self.region.used;
    }

    pub fn rewind(self: *Arena, mark: usize) void {
        if (mark <= self.region.used) self.region.used = mark;
    }
};

pub const Segment = struct {
    ptr: [*]u8,
    len: usize,
};

pub const ZeroCopyResult = union(enum) {
    Remapped: Segment,
    Copied: Segment,
};

pub const PipelineStage = enum(u8) {
    Tokenize,
    Index,
    Rank,
    Process,
};

threadlocal var local_arenas: [4]Arena = undefined;
threadlocal var local_ready: bool = false;

var global_arena: Arena = undefined;
var global_ready: bool = false;

pub fn initGlobal() !void {
    if (global_ready) return;
    global_arena = try Arena.init(GlobalArenaSize, .{ .read = true, .write = true, .exec = false, .shared = true, .locked = false });
    global_ready = true;
}

pub fn deinitGlobal() void {
    if (global_ready) {
        global_arena.deinit();
        global_ready = false;
    }
}

pub fn getGlobalArena() *Arena {
    return &global_arena;
}

pub fn initThreadLocal() !void {
    if (local_ready) return;
    local_arenas[@intFromEnum(PipelineStage.Tokenize)] = try Arena.init(DefaultArenaSize, .{});
    local_arenas[@intFromEnum(PipelineStage.Index)] = try Arena.init(DefaultArenaSize, .{});
    local_arenas[@intFromEnum(PipelineStage.Rank)] = try Arena.init(DefaultArenaSize, .{});
    local_arenas[@intFromEnum(PipelineStage.Process)] = try Arena.init(DefaultArenaSize, .{});
    local_ready = true;
}

pub fn deinitThreadLocal() void {
    if (!local_ready) return;
    inline for (&local_arenas) |*a| a.deinit();
    local_ready = false;
}

pub fn arenaFor(stage: PipelineStage) *Arena {
    return &local_arenas[@intFromEnum(stage)];
}

pub fn alignedCopy(dst_arena: *Arena, src: []const u8, align: usize) !Segment {
    var buf = try dst_arena.alloc(src.len, align);
    std.mem.copy(u8, buf, src);
    return .{ .ptr = buf.ptr, .len = buf.len };
}

fn samePageAligned(p: [*]u8) bool {
    return (@intFromPtr(p) & (PageSize - 1)) == 0;
}

fn pageAlignDown(ptr: [*]u8) [*]u8 {
    return @ptrFromInt(@intFromPtr(ptr) & ~(@as(usize, PageSize - 1)));
}

fn pageAlignUpAddr(addr: usize) usize {
    return (addr + (PageSize - 1)) & ~(@as(usize, PageSize - 1));
}

fn tryRemap(src: []const u8, dst_arena: *Arena) ?Segment {
    // Attempt zero-copy via remapping whole pages into dst arena using MAP_FIXED with shared flags.
    if (src.len == 0) return .{ .ptr = @constCast(src.ptr), .len = 0 };
    const src_base = pageAlignDown(@constCast(src.ptr));
    const offset = @intFromPtr(src.ptr) - @intFromPtr(src_base);
    const map_len = pageAlignUpAddr(offset + src.len) - 0;

    if (!samePageAligned(src_base)) {
        // ensure page alignment
        if (((@intFromPtr(src_base)) & (PageSize - 1)) != 0) return null;
    }

    // Reserve space in dst arena
    const fixed_target_bytes = dst_arena.alloc(map_len, PageSize) catch return null;
    const target_base: [*]u8 = @ptrCast(fixed_target_bytes.ptr);

    const prot: os.PROT = .{ .READ = true, .WRITE = true, .EXEC = false };
    const flags: os.MAP = .{ .PRIVATE = false, .SHARED = true, .FIXED = true, .ANONYMOUS = false };
    // This requires a file-backed or shared mapping; as we don't have the fd here, bail out.
    // In a real kernel with remap primitives, we'd use remap_file_pages or userfaultfd.
    // Return null to fallback to copy.
    _ = prot;
    _ = flags;
    _ = target_base;
    return null;
}

pub fn zeroCopyPass(dst_arena: *Arena, src: []const u8, align: usize) !ZeroCopyResult {
    if (tryRemap(src, dst_arena)) |seg| {
        const sliced: Segment = .{
            .ptr = seg.ptr + (@intFromPtr(src.ptr) - @intFromPtr(@ptrCast(seg.ptr))),
            .len = src.len,
        };
        return .{ .Remapped = sliced };
    }
    const copied = try alignedCopy(dst_arena, src, align);
    return .{ .Copied = copied };
}

// Multi-producer multi-consumer lock-free ring buffer for segments
pub const SegmentRing = struct {
    buf: []Segment,
    mask: usize,
    write_idx: std.atomic.Atomic(usize),
    read_idx: std.atomic.Atomic(usize),

    pub fn init(arena: *Arena, capacity_pow2: usize) !SegmentRing {
        std.debug.assert(std.math.isPowerOfTwo(capacity_pow2));
        const buf = try arena.allocTyped(Segment, capacity_pow2);
        for (buf) |*s| s.* = .{ .ptr = undefined, .len = 0 };
        return .{
            .buf = buf,
            .mask = capacity_pow2 - 1,
            .write_idx = std.atomic.Atomic(usize).init(0),
            .read_idx = std.atomic.Atomic(usize).init(0),
        };
    }

    pub fn push(self: *SegmentRing, seg: Segment) bool {
        var w = self.write_idx.load(.Acquire);
        const r = self.read_idx.load(.Acquire);
        if (w - r == self.buf.len) return false; // full
        self.buf[w & self.mask] = seg;
        self.write_idx.store(w + 1, .Release);
        return true;
    }

    pub fn pop(self: *SegmentRing) ?Segment {
        var r = self.read_idx.load(.Acquire);
        const w = self.write_idx.load(.Acquire);
        if (w == r) return null; // empty
        const seg = self.buf[r & self.mask];
        self.read_idx.store(r + 1, .Release);
        return seg;
    }

    pub fn len(self: *const SegmentRing) usize {
        const w = self.write_idx.load(.Relaxed);
        const r = self.read_idx.load(.Relaxed);
        return w - r;
    }
};

// Region-backed allocator interfacing with Zig std.mem.Allocator
pub const RegionAllocator = struct {
    arena: *Arena,

    pub fn init(arena: *Arena) RegionAllocator {
        return .{ .arena = arena };
    }

    fn allocFn(self_ctx: *anyopaque, len: usize, align: u8, ret_addr: usize) ?[*]u8 {
        _ = ret_addr;
        const self: *RegionAllocator = @ptrCast(@alignCast(self_ctx));
        const got = self.arena.alloc(len, @as(usize, align)) catch return null;
        return got.ptr;
    }

    fn resizeFn(_: *anyopaque, buf: []u8, _: u8, _: usize, _: usize, _: usize) bool {
        _ = buf;
        // Bump allocator cannot resize
        return false;
    }

    fn freeFn(_: *anyopaque, _: []u8, _: u8, _: usize, _: usize) void {}

    pub fn allocator(self: *RegionAllocator) std.mem.Allocator {
        return .{
            .ptr = self,
            .vtable = &.{
                .alloc = allocFn,
                .resize = resizeFn,
                .free = freeFn,
            },
        };
    }
};

// Shared immutable slab: allocate once, share many readers
pub const Slab = struct {
    ptr: [*]u8,
    len: usize,

    pub fn fromArena(arena: *Arena, src: []const u8) !Slab {
        const dst = try arena.alloc(src.len, std.mem.page_size);
        std.mem.copy(u8, dst, src);
        // mprotect read-only for safety
        _ = os.mprotect(@ptrCast(dst.ptr), dst.len, .{ .READ = true, .WRITE = false, .EXEC = false }) catch {};
        return .{ .ptr = dst.ptr, .len = dst.len };
    }

    pub fn asSlice(self: *const Slab) []const u8 {
        return self.ptr[0..self.len];
    }
};

// File-backed mapping utility
pub fn mapFile(path: []const u8, writable: bool) ![]u8 {
    var gpa = std.heap.page_allocator;
    var file = try std.fs.cwd().openFileZ(std.mem.span(std.mem.dupeZ(gpa, u8, path) catch unreachable), .{ .read = true, .write = writable });
    defer file.close();
    const stat = try file.stat();
    const size = @as(usize, @intCast(stat.size));
    if (size == 0) return error.EmptyFile;
    const prot: os.PROT = .{ .READ = true, .WRITE = writable, .EXEC = false };
    const flags: os.MAP = .{ .SHARED = true, .ANONYMOUS = false };
    const addr = try os.mmap(null, size, prot, flags, file.handle, 0);
    return @as([*]u8, @ptrCast(addr))[0..size];
}

test "arena alloc and rewind" {
    var a = try Arena.init(4 * MiB, .{});
    defer a.deinit();

    const mark = a.snapshot();
    const buf = try a.alloc(1234, 64);
    try std.testing.expect(buf.len == 1234);
    a.rewind(mark);
    try std.testing.expect(a.region.used == mark);
}

test "segment ring basic" {
    var a = try Arena.init(1 * MiB, .{});
    defer a.deinit();

    var ring = try SegmentRing.init(&a, 8);
    try std.testing.expect(ring.len() == 0);
    try std.testing.expect(ring.pop() == null);
    try std.testing.expect(ring.push(.{ .ptr = @ptrFromInt(0x1000), .len = 16 }));
    try std.testing.expect(ring.len() == 1);
    try std.testing.expect(ring.pop() != null);
}
