// src/core/tensor.zig
const std = @import("std");

pub fn Tensor(comptime T: type, comptime order: usize) type {
    return struct {
        const Self = @This();
        shape: [order]usize,
        strides: [order]usize,
        data: []T,
        allocator: std.mem.Allocator,

        pub fn init(allocator: std.mem.Allocator, shape: [order]usize) !Self {
            var total: usize = 1;
            var strides: [order]usize = undefined;
            // row-major
            var i: isize = order - 1;
            var stride: usize = 1;
            while (i >= 0) : (i -= 1) {
                const ui = @as(usize, @intCast(i));
                strides[ui] = stride;
                stride *= shape[ui];
                total *= shape[ui];
            }
            const data = try allocator.alloc(T, total);
            return .{ .shape = shape, .strides = strides, .data = data, .allocator = allocator };
        }

        pub fn fromSlice(allocator: std.mem.Allocator, shape: [order]usize, slice: []const T) !Self {
            var t = try Self.init(allocator, shape);
            std.mem.copy(T, t.data, slice);
            return t;
        }

        pub fn deinit(self: *Self) void {
            if (self.data.len != 0) self.allocator.free(self.data);
            self.* = undefined;
        }

        pub inline fn index(self: *const Self, idx: [order]usize) usize {
            var flat: usize = 0;
            var i: usize = 0;
            while (i < order) : (i += 1) flat += idx[i] * self.strides[i];
            return flat;
        }

        pub inline fn at(self: *const Self, idx: [order]usize) *const T {
            return &self.data[self.index(idx)];
        }

        pub inline fn atMut(self: *Self, idx: [order]usize) *T {
            return &self.data[self.index(idx)];
        }

        pub fn fill(self: *Self, value: T) void {
            for (self.data) |*p| p.* = value;
        }

        pub fn map(self: *const Self, comptime F: fn (T) T, allocator: std.mem.Allocator) !Self {
            var out = try Self.init(allocator, self.shape);
            var i: usize = 0;
            while (i < self.data.len) : (i += 1) out.data[i] = F(self.data[i]);
            return out;
        }

        pub fn add(self: *const Self, other: *const Self, allocator: std.mem.Allocator) !Self {
            std.debug.assert(std.mem.eql(usize, &self.shape, &other.shape));
            var out = try Self.init(allocator, self.shape);
            if (@typeInfo(T) == .Float or @typeInfo(T) == .Int) {
                const V = @Vector(8, T);
                var i: usize = 0;
                while (i + 8 <= self.data.len) : (i += 8) {
                    const a: V = self.data[i..][0..8].*;
                    const b: V = other.data[i..][0..8].*;
                    const c: V = a + b;
                    out.data[i..][0..8].* = c;
                }
                while (i < self.data.len) : (i += 1) out.data[i] = self.data[i] + other.data[i];
            } else {
                for (self.data, 0..) |v, i| out.data[i] = v + other.data[i];
            }
            return out;
        }

        pub fn mul(self: *const Self, other: *const Self, allocator: std.mem.Allocator) !Self {
            std.debug.assert(std.mem.eql(usize, &self.shape, &other.shape));
            var out = try Self.init(allocator, self.shape);
            if (@typeInfo(T) == .Float or @typeInfo(T) == .Int) {
                const V = @Vector(8, T);
                var i: usize = 0;
                while (i + 8 <= self.data.len) : (i += 8) {
                    const a: V = self.data[i..][0..8].*;
                    const b: V = other.data[i..][0..8].*;
                    const c: V = a * b;
                    out.data[i..][0..8].* = c;
                }
                while (i < self.data.len) : (i += 1) out.data[i] = self.data[i] * other.data[i];
            } else {
                for (self.data, 0..) |v, i| out.data[i] = v * other.data[i];
            }
            return out;
        }

        pub fn fused_add_multiply(self: *const Self, a: T, other: *const Self, b: T, allocator: std.mem.Allocator) !Self {
            std.debug.assert(std.mem.eql(usize, &self.shape, &other.shape));
            var out = try Self.init(allocator, self.shape);
            if (@typeInfo(T) == .Float or @typeInfo(T) == .Int) {
                const V = @Vector(8, T);
                const va: V = @splat(a);
                const vb: V = @splat(b);
                var i: usize = 0;
                while (i + 8 <= self.data.len) : (i += 8) {
                    const x: V = self.data[i..][0..8].*;
                    const y: V = other.data[i..][0..8].*;
                    const r: V = va * x + vb * y;
                    out.data[i..][0..8].* = r;
                }
                while (i < self.data.len) : (i += 1) out.data[i] = a * self.data[i] + b * other.data[i];
            } else {
                for (self.data, 0..) |v, i| out.data[i] = a * v + b * other.data[i];
            }
            return out;
        }

        pub fn matmul(self: *const Self, other: *const Self, allocator: std.mem.Allocator) !Self {
            comptime std.debug.assert(order == 2);
            comptime std.debug.assert(order == other.shape.len);
            std.debug.assert(self.shape[1] == other.shape[0]);
            const m = self.shape[0];
            const k = self.shape[1];
            const n = other.shape[1];
            var out = try Self.init(allocator, .{ m, n });
            out.fill(@as(T, 0));
            var i: usize = 0;
            while (i < m) : (i += 1) {
                var j: usize = 0;
                while (j < n) : (j += 1) {
                    var acc: T = 0;
                    var p: usize = 0;
                    if (@typeInfo(T) == .Float) {
                        const VV = @Vector(8, T);
                        while (p + 8 <= k) : (p += 8) {
                            const a: VV = .{
                                self.data[i * k + p + 0], self.data[i * k + p + 1], self.data[i * k + p + 2], self.data[i * k + p + 3],
                                self.data[i * k + p + 4], self.data[i * k + p + 5], self.data[i * k + p + 6], self.data[i * k + p + 7],
                            };
                            const b: VV = .{
                                other.data[(p + 0) * n + j], other.data[(p + 1) * n + j], other.data[(p + 2) * n + j], other.data[(p + 3) * n + j],
                                other.data[(p + 4) * n + j], other.data[(p + 5) * n + j], other.data[(p + 6) * n + j], other.data[(p + 7) * n + j],
                            };
                            const prod = a * b;
                            acc += prod[0] + prod[1] + prod[2] + prod[3] + prod[4] + prod[5] + prod[6] + prod[7];
                        }
                    }
                    while (p < k) : (p += 1) acc += self.data[i * k + p] * other.data[p * n + j];
                    out.data[i * n + j] = acc;
                }
            }
            return out;
        }

        pub fn conv2d(
            input: *const Self, // [N, C, H, W]
            kernel: *const Tensor(T, 4), // [F, C, KH, KW]
            stride_h: usize,
            stride_w: usize,
            pad_h: usize,
            pad_w: usize,
            allocator: std.mem.Allocator,
        ) !Tensor(T, 4) {
            comptime std.debug.assert(order == 4);
            const N = input.shape[0];
            const C = input.shape[1];
            const H = input.shape[2];
            const W = input.shape[3];
            const F = kernel.shape[0];
            const KH = kernel.shape[2];
            const KW = kernel.shape[3];
            const OH = (H + 2 * pad_h - KH) / stride_h + 1;
            const OW = (W + 2 * pad_w - KW) / stride_w + 1;

            var out = try Tensor(T, 4).init(allocator, .{ N, F, OH, OW });
            out.fill(@as(T, 0));

            var n: usize = 0;
            while (n < N) : (n += 1) {
                var f: usize = 0;
                while (f < F) : (f += 1) {
                    var oh: usize = 0;
                    while (oh < OH) : (oh += 1) {
                        const ih_base = oh * stride_h;
                        var ow: usize = 0;
                        while (ow < OW) : (ow += 1) {
                            const iw_base = ow * stride_w;
                            var acc: T = 0;
                            var c: usize = 0;
                            while (c < C) : (c += 1) {
                                var kh: usize = 0;
                                while (kh < KH) : (kh += 1) {
                                    const ih = @as(isize, @intCast(ih_base + kh)) - @as(isize, @intCast(pad_h));
                                    if (ih < 0 or ih >= @as(isize, @intCast(H))) continue;
                                    var kw: usize = 0;
                                    while (kw < KW) : (kw += 1) {
                                        const iw = @as(isize, @intCast(iw_base + kw)) - @as(isize, @intCast(pad_w));
                                        if (iw < 0 or iw >= @as(isize, @intCast(W))) continue;
                                        const in_idx = (((n * C + c) * H + @as(usize, @intCast(ih))) * W + @as(usize, @intCast(iw)));
                                        const k_idx = (((f * C + c) * KH + kh) * KW + kw);
                                        acc += input.data[in_idx] * kernel.data[k_idx];
                                    }
                                }
                            }
                            out.data[(((n * F + f) * OH + oh) * OW + ow)] = acc;
                        }
                    }
                }
            }
            return out;
        }

        pub fn einsum(self: *const Self, other: *const Self, spec: []const u8, allocator: std.mem.Allocator) !Self {
            // Minimalistic einsum: supports "ik,kj->ij" matrix multiply and "ij,j->i" vector reduction patterns.
            // Parse spec
            if (std.mem.eql(u8, spec, "ik,kj->ij")) {
                return try self.matmul(other, allocator);
            } else if (std.mem.eql(u8, spec, "ij,j->i")) {
                comptime std.debug.assert(order == 2);
                std.debug.assert(other.shape.len == 1);
                const I = self.shape[0];
                const J = self.shape[1];
                std.debug.assert(other.shape[0] == J);
                var out = try Self.init(allocator, .{ I, 1 });
                var i: usize = 0;
                while (i < I) : (i += 1) {
                    var acc: T = 0;
                    var j: usize = 0;
                    const V = @Vector(8, T);
                    if (@typeInfo(T) == .Float) {
                        while (j + 8 <= J) : (j += 8) {
                            const a: V = self.data[i * J + j ..][0..8].*;
                            const b: V = .{
                                other.data[j + 0], other.data[j + 1], other.data[j + 2], other.data[j + 3],
                                other.data[j + 4], other.data[j + 5], other.data[j + 6], other.data[j + 7],
                            };
                            const p = a * b;
                            acc += p[0] + p[1] + p[2] + p[3] + p[4] + p[5] + p[6] + p[7];
                        }
                    }
                    while (j < J) : (j += 1) acc += self.data[i * J + j] * other.data[j];
                    out.data[i] = acc;
                }
                return out;
            } else {
                return error.UnsupportedEinsum;
            }
        }
    };
}

test "fused add multiply works" {
    var gpa = std.heap.page_allocator;
