// src/index/ssi.zig
const std = @import("std");
const os = std.posix;

pub const SSIHeader = packed struct {
    magic: u32 = 0x534A4944, // 'SJID'
    version: u32 = 1,
    segments: u64 = 0,
    index_offset: u64 = 0,
    index_count: u64 = 0,
    data_offset: u64 = 0,
    data_size: u64 = 0,
};

pub const Entry = packed struct {
    key: u128,
    simhash: u64,
    file_offset: u64,
    token_count: u32,
    reserved: u32,
};

pub const SSI = struct {
    file: std.fs.File,
    map: []u8,
    header: *volatile SSIHeader,
    entries: []Entry,

    pub fn openOrCreate(path: []const u8, initial_capacity: usize) !SSI {
        var file = try std.fs.cwd().createFile(path, .{ .truncate = false, .read = true, .write = true });
        var stat = file.stat() catch |e| {
            file.close();
            return e;
        };
        if (stat.size == 0) {
            const init_size: usize = std.math.ceilPowerOfTwo(usize, @max(4 * 1024, initial_capacity * @sizeOf(Entry) + @sizeOf(SSIHeader))) catch unreachable;
            try file.setEndPos(init_size);
        }
        const len = @as(usize, @intCast((try file.stat()).size));
        const prot: os.PROT = .{ .READ = true, .WRITE = true, .EXEC = false };
        const flags: os.MAP = .{ .SHARED = true, .ANONYMOUS = false };
        const addr = try os.mmap(null, len, prot, flags, file.handle, 0);
        const map: []u8 = @as([*]u8, @ptrCast(addr))[0..len];

        var header: *SSIHeader = @ptrCast(map.ptr);
        if (header.magic != 0x534A4944) {
            header.* = .{
                .magic = 0x534A4944,
                .version = 1,
                .segments = 0,
                .index_offset = @sizeOf(SSIHeader),
                .index_count = 0,
                .data_offset = std.math.alignForward(usize, @sizeOf(SSIHeader) + initial_capacity * @sizeOf(Entry), 4096),
                .data_size = 0,
            };
        }

        const entries_slice = map[header.index_offset..header.index_offset + initial_capacity * @sizeOf(Entry)];
        const entries = std.mem.bytesAsSlice(Entry, entries_slice);

        return .{
            .file = file,
            .map = map,
            .header = @ptrCast(map.ptr),
            .entries = entries,
        };
    }

    pub fn close(self: *SSI) void {
        if (self.map.len > 0) { _ = os.munmap(@ptrCast(self.map.ptr), self.map.len); }
        self.file.close();
        self.* = undefined;
    }

    pub fn ensureCapacity(self: *SSI, needed: usize) !void {
        if (needed <= self.entries.len) return;
        const new_entries = std.math.ceilPowerOfTwo(usize, needed) catch unreachable;
        const new_size = std.math.alignForward(usize, self.header.data_offset + self.header.data_size + (new_entries - self.entries.len) * @sizeOf(Entry), 4096);
        try self.file.setEndPos(new_size);
        // Remap
        _ = os.munmap(@ptrCast(self.map.ptr), self.map.len);
        const addr = try os.mmap(null, new_size, .{ .READ = true, .WRITE = true, .EXEC = false }, .{ .SHARED = true, .ANONYMOUS = false }, self.file.handle, 0);
        self.map = @as([*]u8, @ptrCast(addr))[0..new_size];
        self.header = @ptrCast(self.map.ptr);
        self.entries = std.mem.bytesAsSlice(Entry, self.map[self.header.index_offset..self.header.index_offset + new_entries * @sizeOf(Entry)]);
    }

    pub fn hashTokens(tokens: []const u32) u128 {
        var h0: u64 = 0xcbf29ce484222325;
        var h1: u64 = 0x100000001b3;
        for (tokens) |t| {
            h0 = (h0 ^^ @as(u64, t)) * 0x100000001b3;
            h1 = (h1 +% (@as(u64, t) * 0x9e3779b185ebca87)) ^| (h0 << 13);
            h0 = std.math.rotr(u64, h0, @as(u6, 7));
        }
        return (@as(u128, h0) << 64) | h1;
    }

    pub fn simHash(tokens: []const u32) u64 {
        var acc: [64]i32 = .{0} ** 64;
        for (tokens) |t| {
            var x: u64 = @bitCast(t *% 0x9e3779b1);
            x ^= x >> 33;
            x *= 0xff51afd7ed558ccd;
            x ^= x >> 33;
            x *= 0xc4ceb9fe1a85ec53;
            x ^= x >> 33;
            var i: usize = 0;
            while (i < 64) : (i += 1) {
                if ((x >> @intCast(i)) & 1 == 1) acc[i] += 1 else acc[i] -= 1;
            }
        }
        var out: u64 = 0;
        var i: usize = 0;
        while (i < 64) : (i += 1) {
            if (acc[i] >= 0) out |= (@as(u64, 1) << @intCast(i));
        }
        return out;
    }

    fn hamming(a: u64, b: u64) u32 {
        return @intCast(std.math.popCount(u64, a ^ b));
    }

    pub fn insert(self: *SSI, tokens: []const u32, file_offset: u64) !void {
        const key = hashTokens(tokens);
        const sh = simHash(tokens);
        try self.ensureCapacity(@as(usize, @intCast(self.header.index_count)) + 1);
        var idx: usize = 0;
        // binary search insert position by key
        var lo: usize = 0;
        var hi: usize = @as(usize, @intCast(self.header.index_count));
        while (lo < hi) {
            const mid = (lo + hi) / 2;
            const k = self.entries[mid].key;
            if (k < key) lo = mid + 1 else hi = mid;
        }
        idx = lo;

        // shift
        var i = @as(usize, @intCast(self.header.index_count));
        while (i > idx) : (i -= 1) self.entries[i] = self.entries[i - 1];

        self.entries[idx] = .{
            .key = key,
            .simhash = sh,
            .file_offset = file_offset,
            .token_count = @as(u32, @intCast(tokens.len)),
            .reserved = 0,
        };
        self.header.index_count += 1;
        self.header.segments += 1;
    }

    pub fn retrieve_similar_segments(self: *const SSI, query: []const u32, k: usize, out: []Entry) usize {
        if (k == 0 or out.len < k) return 0;
        const qh = hashTokens(query);
        const qsh = simHash(query);
        // Find nearest by key vicinity then rank by Hamming distance
        var lo: usize = 0;
        var hi: usize = @as(usize, @intCast(self.header.index_count));
        while (lo < hi) {
            const mid = (lo + hi) / 2;
            const kx = self.entries[mid].key;
            if (kx < qh) lo = mid + 1 else hi = mid;
        }
        // Explore window around lo
        var best = std.PriorityQueue(Entry, void, struct {
            pub fn lessThan(_: void, a: Entry, b: Entry) bool {
                // min-heap by negative distance to keep largest distance at top and pop it
                return a.reserved < b.reserved;
            }
        }{ .{}}).init(std.heap.page_allocator);
        defer best.deinit();

        const radius: usize = 4096; // search band
        const start = if (lo > radius) lo - radius else 0;
        const end = @min(lo + radius, @as(usize, @intCast(self.header.index_count)));

        var i: usize = start;
        while (i < end) : (i += 1) {
            const e = self.entries[i];
            const d = hamming(e.simhash, qsh);
            var cand = e;
            cand.reserved = d;
            if (best.len < k) {
                best.add(cand) catch {};
            } else {
                const top = best.peek() orelse cand;
                if (d < top.reserved) {
                    _ = best.remove();
                    best.add(cand) catch {};
                }
            }
        }

        var count: usize = best.len;
        if (count > k) count = k;
        var idx: isize = @as(isize, @intCast(count));
        while (idx > 0) : (idx -= 1) {
            out[@as(usize, @intCast(idx - 1))] = best.remove();
        }
        return count;
    }
};

test "ssi insert and retrieve" {
    var ssi = try SSI.openOrCreate("test.ssi", 1024);
    defer {
        ssi.close();
        std.fs.cwd().deleteFile("test.ssi") catch {};
    }

    var t0 = [_]u32{1,2,3,4,5,6,7,8};
    var t1 = [_]u32{1,2,3,44,5,6,7,8};
    var t2 = [_]u32{9,9,9,9,9,9,9,9};
    try ssi.insert(&t0, 0);
    try ssi.insert(&t1, 128);
    try ssi.insert(&t2, 256);

    var out: [2]Entry = undefined;
    const n = ssi.retrieve_similar_segments(&t0, 2, out[0..]);
    try std.testing.expect(n >= 1);
}
