// src/ranker/ranker.zig
const std = @import("std");

pub const SegmentInfo = struct {
    start_offset: u64,
    token_ids: []const u32,
    timestamp_order: u64, // larger = more recent
};

pub const ScoredSegment = struct {
    start_offset: u64,
    score: f64,
    ref_index: usize,
};

fn lowercaseEq(a: u8, b: u8) bool {
    const A = if (a >= 'A' and a <= 'Z') a + 32 else a;
    const B = if (b >= 'A' and b <= 'Z') b + 32 else b;
    return A == B;
}

fn isCapitalized(word: []const u8) bool {
    var i: usize = 0;
    var saw_upper = false;
    while (i < word.len) : (i += 1) {
        const c = word[i];
        if (c >= 'A' and c <= 'Z') saw_upper = true;
        if (c == '_' or c == '-' or c == '\'') continue;
        if (c < 32) return false;
    }
    return saw_upper;
}

fn jaccard(a: []const u32, b: []const u32) f64 {
    var setA = std.AutoHashMap(u32, void).init(std.heap.page_allocator);
    defer setA.deinit();
    for (a) |t| { setA.put(t, {}) catch {}; }

    var inter: usize = 0;
    var union: usize = setA.count();

    var seen = std.AutoHashMap(u32, void).init(std.heap.page_allocator);
    defer seen.deinit();

    for (b) |t| {
        if (setA.contains(t)) inter += 1;
        if (!seen.contains(t)) {
            _ = seen.put(t, {}) catch {};
            if (!setA.contains(t)) union += 1;
        }
    }
    if (union == 0) return 0;
    return @as(f64, @floatFromInt(inter)) / @as(f64, @floatFromInt(union));
}

pub const Ranker = struct {
    allocator: std.mem.Allocator,
    idf: std.AutoHashMap(u32, f32),
    total_docs: usize,

    pub fn init(allocator: std.mem.Allocator) Ranker {
        return .{
            .allocator = allocator,
            .idf = std.AutoHashMap(u32, f32).init(allocator),
            .total_docs = 0,
        };
    }

    pub fn deinit(self: *Ranker) void {
        self.idf.deinit();
        self.* = undefined;
    }

    pub fn ingest(self: *Ranker, segments: []const SegmentInfo) void {
        // Build IDF estimations
        var df = std.AutoHashMap(u32, usize).init(self.allocator);
        defer df.deinit();

        for (segments) |seg| {
            var seen = std.AutoHashMap(u32, void).init(self.allocator);
            defer seen.deinit();
            for (seg.token_ids) |t| {
                if (!seen.contains(t)) {
                    _ = seen.put(t, {}) catch {};
                    const e = df.getOrPut(t) catch continue;
                    if (!e.found_existing) e.value_ptr.* = 0;
                    e.value_ptr.* += 1;
                }
            }
        }
        self.total_docs += segments.len;
        var it = df.iterator();
        while (it.next()) |kv| {
            const tok = kv.key_ptr.*;
            const dfi = kv.value_ptr.*;
            const idf_val: f32 = @floatCast(std.math.log((@as(f64, @floatFromInt(self.total_docs)) + 1.0) / (@as(f64, @floatFromInt(dfi)) + 1.0)) + 1.0);
            _ = self.idf.put(tok, idf_val) catch {};
        }
    }

    fn tfidf(self: *const Ranker, query: []const u32, segment: []const u32) f64 {
        // TF: raw count in segment, normalized by length
        var tf_sum: f64 = 0;
        for (query) |q| {
            var cnt: usize = 0;
            for (segment) |t| if (t == q) cnt += 1;
            const tf = @as(f64, @floatFromInt(cnt)) / @as(f64, @floatFromInt(segment.len) + 1e-9);
            const idf = self.idf.get(q) orelse 1.0;
            tf_sum += tf * idf;
        }
        return tf_sum;
    }

    fn positionalDecay(current_tail: u64, seg_order: u64) f64 {
        if (current_tail <= seg_order) return 1.0;
        const d = @as(f64, @floatFromInt(current_tail - seg_order));
        return 1.0 / (1.0 + 0.001 * d);
    }

    fn entityDensity(seg_bytes: []const u8) f64 {
        // crude tokenization on spaces
        var it = std.mem.splitScalar(u8, seg_bytes, ' ');
        var count_cap: usize = 0;
        var total: usize = 0;
        while (it.next()) |w| {
            if (w.len == 0) continue;
            total += 1;
            if (isCapitalized(w)) count_cap += 1;
        }
        if (total == 0) return 0;
        return @as(f64, @floatFromInt(count_cap)) / @as(f64, @floatFromInt(total));
    }

    pub fn rankTopK(
        self: *const Ranker,
        query_tokens: []const u32,
        query_bytes: []const u8,
        segments: []const SegmentInfo,
        top_k: usize,
        out: []ScoredSegment,
    ) usize {
        var pq = std.PriorityQueue(ScoredSegment, void, struct {
            pub fn lessThan(_: void, a: ScoredSegment, b: ScoredSegment) bool {
                // min-heap by score
                return a.score < b.score;
            }
        }{ .{}}).init(self.allocator);
        defer pq.deinit();

        var i: usize = 0;
        const tail = if (segments.len > 0) segments[segments.len - 1].timestamp_order else 0;
        while (i < segments.len) : (i += 1) {
            const seg = segments[i];
            // weights
            const w_tfidf: f64 = 0.45;
            const w_pos: f64 = 0.25;
            const w_ent: f64 = 0.10;
            const w_sim: f64 = 0.20;
            const tfidf_score = self.tfidf(query_tokens, seg.token_ids);
            const pos_score = positionalDecay(tail, seg.timestamp_order);
            // Entity density uses bytes; assume caller provides raw text if available; here we simulate with token bytes
            const ent_score = entityDensity(query_bytes);
            const sim_score = jaccard(query_tokens, seg.token_ids);
            const score = w_tfidf * tfidf_score + w_pos * pos_score + w_ent * ent_score + w_sim * sim_score;

            const item = ScoredSegment{ .start_offset = seg.start_offset, .score = score, .ref_index = i };

            if (pq.len < top_k) {
                pq.add(item) catch {};
            } else {
                const top = pq.peek().?;
                if (item.score > top.score) {
                    _ = pq.remove();
                    pq.add(item) catch {};
                }
            }
        }

        var count: usize = pq.len;
        if (count > top_k) count = top_k;
        var idx: isize = @as(isize, @intCast(count));
        while (idx > 0) : (idx -= 1) {
            out[@as(usize, @intCast(idx - 1))] = pq.remove();
        }
        return count;
    }
};

test "ranker basic" {
    var gpa = std.heap.page_allocator;
    var r = Ranker.init(gpa);
    defer r.deinit();

    var segs: [3]SegmentInfo = .{
        .{ .start_offset = 0, .token_ids = &[_]u32{1,2,3}, .timestamp_order = 1 },
        .{ .start_offset = 100, .token_ids = &[_]u32{2,3,4}, .timestamp_order = 2 },
        .{ .start_offset = 200, .token_ids = &[_]u32{3,4,5}, .timestamp_order = 3 },
    };
    r.ingest(&segs);

    var out: [2]ScoredSegment = undefined;
    const n = r.rankTopK(&[_]u32{3}, "Entity Alice", &segs, 2, out[0..]);
    try std.testing.expect(n == 2);
    try std.testing.expect(out[0].score >= out[1].score);
}
