// src/tokenizer/mgt.zig
const std = @import("std");

pub const NodeId = u32;

pub const Flags = packed struct {
    anchor: bool = false,
    unknown: bool = false,
    dynamic: bool = false,
    reserved: u13 = 0,
};

pub const Node = packed struct {
    // Radix edge prefix (compressed)
    plen: u8,
    pbytes: [15]u8,
    first_child: NodeId,
    sibling: NodeId,
    token_id: u32, // 0xFFFF_FFFF -> non-terminal
    flags: Flags,
    freq: u16,
};

pub const Trie = struct {
    arena: std.mem.Allocator,
    nodes: std.ArrayList(Node),
    root: NodeId,

    pub fn init(arena: std.mem.Allocator) !Trie {
        var nodes = std.ArrayList(Node).init(arena);
        const rootId: NodeId = 0;
        try nodes.append(.{
            .plen = 0,
            .pbytes = .{0} ** 15,
            .first_child = 0xFFFF_FFFF,
            .sibling = 0xFFFF_FFFF,
            .token_id = 0xFFFF_FFFF,
            .flags = .{},
            .freq = 0,
        });
        return .{ .arena = arena, .nodes = nodes, .root = rootId };
    }

    pub fn deinit(self: *Trie) void {
        self.nodes.deinit();
        self.* = undefined;
    }

    fn newNode(self: *Trie, label: []const u8, token_id: u32, flags: Flags) !NodeId {
        var n: Node = .{
            .plen = @intCast(@min(label.len, 15)),
            .pbytes = .{0} ** 15,
            .first_child = 0xFFFF_FFFF,
            .sibling = 0xFFFF_FFFF,
            .token_id = token_id,
            .flags = flags,
            .freq = 1,
        };
        std.mem.copy(u8, n.pbytes[0..n.plen], label[0..n.plen]);
        try self.nodes.append(n);
        return @intCast(self.nodes.items.len - 1);
    }

    fn commonPrefix(a: []const u8, b: []const u8) usize {
        var i: usize = 0;
        const m = @min(a.len, b.len);
        while (i < m and a[i] == b[i]) : (i += 1) {}
        return i;
    }

    fn childIter(self: *const Trie, nid: NodeId) struct {
        cur: NodeId,
        nodes: []const Node,
    } {
        return .{ .cur = self.nodes.items[@intCast(nid)].first_child, .nodes = self.nodes.items };
    }

    fn childNext(it: *struct { cur: NodeId, nodes: []const Node }) ?NodeId {
        if (it.cur == 0xFFFF_FFFF) return null;
        const ret = it.cur;
        it.cur = it.nodes[@intCast(it.cur)].sibling;
        return ret;
    }

    fn insertPath(self: *Trie, parent: NodeId, key: []const u8, token_id: u32, flags: Flags) !void {
        // Greedy radix insertion
        var prev: ?NodeId = null;
        var it = self.childIter(parent);
        while (childNext(&it)) |cid| {
            var node = &self.nodes.items[@intCast(cid)];
            const label = node.pbytes[0..node.plen];
            const cp = commonPrefix(key, label);
            if (cp == 0) {
                prev = cid;
                continue;
            }
            if (cp < label.len) {
                // Split node
                const suffix_label = label[cp..];
                const suffix_node = try self.newNode(suffix_label, node.token_id, node.flags);
                self.nodes.items[@intCast(suffix_node)].first_child = node.first_child;

                // Update current to common prefix
                node.plen = @intCast(cp);
                var tmpb: [15]u8 = .{0} ** 15;
                std.mem.copy(u8, tmpb[0..cp], label[0..cp]);
                node.pbytes = tmpb;
                node.token_id = 0xFFFF_FFFF;
                node.flags = .{};
                node.first_child = suffix_node;

                // Insert new child for rest of key
                const rest = key[cp..];
                const new_child = try self.newNode(rest, token_id, flags);
                self.nodes.items[@intCast(new_child)].sibling = self.nodes.items[@intCast(cid)].first_child;
                self.nodes.items[@intCast(cid)].first_child = new_child;
                return;
            } else {
                // full match of label, continue down
                const rest = key[cp..];
                if (rest.len == 0) {
                    // terminal
                    node.token_id = token_id;
                    node.flags = flags;
                    node.freq +%= 1;
                    return;
                } else {
                    return self.insertPath(cid, rest, token_id, flags);
                }
            }
        }
        // no child matched; append as new child
        const new_child = try self.newNode(key, token_id, flags);
        if (prev) |p| {
            self.nodes.items[@intCast(new_child)].sibling = self.nodes.items[@intCast(p)].sibling;
            self.nodes.items[@intCast(p)].sibling = new_child;
        } else {
            // first child of parent
            self.nodes.items[@intCast(parent)].first_child = new_child;
        }
    }

    fn deterministicTokenId(bytes: []const u8) u32 {
        var h: u64 = 0xcbf29ce484222325;
        for (bytes) |b| {
            h = (h ^^ b) * 0x100000001b3;
            h ^= h >> 33;
        }
        return @intCast(h ^ (h >> 32));
    }

    pub fn insertToken(self: *Trie, token_bytes: []const u8, anchor: bool) !u32 {
        const tid = deterministicTokenId(token_bytes) | (if (anchor) 0x80000000 else 0);
        try self.insertPath(self.root, token_bytes, tid, .{ .anchor = anchor, .dynamic = true });
        return tid;
    }

    fn findLongest(self: *const Trie, start: usize, bytes: []const u8) struct { end: usize, token_id: u32 } {
        var nid = self.root;
        var pos = start;
        var last_term: struct { end: usize, token_id: u32 } = .{ .end = start, .token_id = 0xFFFF_FFFF };

        while (true) {
            const node = self.nodes.items[@intCast(nid)];
            if (node.token_id != 0xFFFF_FFFF) last_term = .{ .end = pos, .token_id = node.token_id };

            // descend to matching child
            var it = self.childIter(nid);
            var advanced = false;
            while (childNext(&it)) |cid| {
                const lbl = self.nodes.items[@intCast(cid)].pbytes[0..self.nodes.items[@intCast(cid)].plen];
                if (pos + lbl.len <= bytes.len and std.mem.eql(u8, lbl, bytes[pos .. pos + lbl.len])) {
                    nid = cid;
                    pos += lbl.len;
                    advanced = true;
                    break;
                }
            }
            if (!advanced) break;
        }
        return last_term;
    }

    pub fn tokenize(self: *Trie, input: []const u8, out_ids: []u32) usize {
        var pos: usize = 0;
        var count: usize = 0;

        while (pos < input.len and count < out_ids.len) {
            // skip spaces and inject anchor tokens for structural elements
            const c = input[pos];
            if (c == '\n') {
                out_ids[count] = self.insertToken("*ANCHOR:LF", true) catch 0;
                count += 1;
                pos += 1;
                continue;
            } else if (c == '\t') {
                out_ids[count] = self.insertToken("*ANCHOR:TAB", true) catch 0;
                count += 1;
                pos += 1;
                continue;
            } else if (c <= 0x20) {
                pos += 1;
                continue;
            }

            const match = self.findLongest(pos, input);
            if (match.token_id != 0xFFFF_FFFF and match.end > pos) {
                out_ids[count] = match.token_id;
                count += 1;
                pos = match.end;
                continue;
            }

            // Unknown: attempt sub-morpheme split by vowels/consonants boundary
            var end = pos + 1;
            while (end < input.len and end - pos < 8) : (end += 1) {
                const ch = input[end - 1];
                if (ch == 'a' or ch == 'e' or ch == 'i' or ch == 'o' or ch == 'u' or ch == 'y') break;
            }
            const piece = input[pos..end];
            const tid = self.insertToken(piece, false) catch deterministicTokenId(piece);
            out_ids[count] = tid;
            count += 1;
            pos = end;
        }

        return count;
    }
};

test "mgt basic tokenize" {
    var gpa = std.heap.page_allocator;
    var trie = try Trie.init(gpa);
    defer trie.deinit();

    _ = try trie.insertToken("Alice", true);
    _ = try trie.insertToken("went", false);
    _ = try trie.insertToken("home", false);

    var ids: [16]u32 = undefined;
    const n = trie.tokenize("Alice went home\n", ids[0..]);
    try std.testing.expect(n >= 4);
}
