// src/optimizer/sfd.zig
const std = @import("std");

pub const SFD = struct {
    lr: f32,
    beta_grad: f32,
    beta_fisher: f32,
    eps: f32,
    clip_min: f32,
    clip_max: f32,

    // state
    m: []f32, // EMA of gradients
    f: []f32, // Fisher diagonal estimate

    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, param_count: usize, lr: f32) !SFD {
        return .{
            .lr = lr,
            .beta_grad = 0.9,
            .beta_fisher = 0.95,
            .eps = 1e-8,
            .clip_min = 1e-6,
            .clip_max = 1e+2,
            .m = try allocator.alloc(f32, param_count),
            .f = try allocator.alloc(f32, param_count),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *SFD) void {
        if (self.m.len > 0) self.allocator.free(self.m);
        if (self.f.len > 0) self.allocator.free(self.f);
        self.* = undefined;
    }

    pub fn zero(self: *SFD) void {
        std.mem.set(f32, self.m, 0);
        std.mem.set(f32, self.f, 0);
    }

    fn spectralClip(self: *const SFD, x: f32) f32 {
        var y = x;
        if (y < self.clip_min) y = self.clip_min;
        if (y > self.clip_max) y = self.clip_max;
        return y;
    }

    pub fn update(self: *SFD, params: []f32, grads: []const f32) void {
        std.debug.assert(params.len == grads.len);
        // Update state
        var i: usize = 0;
        while (i < params.len) : (i += 1) {
            // EMA gradient
            self.m[i] = self.beta_grad * self.m[i] + (1.0 - self.beta_grad) * grads[i];

            // Fisher diag estimate via squared grad EMA
            const g2 = grads[i] * grads[i];
            self.f[i] = self.beta_fisher * self.f[i] + (1.0 - self.beta_fisher) * g2;

            const f_clip = spectralClip(self, self.f[i]);
            // Precondition and update
            const denom = @sqrt(f_clip) + self.eps;
            const step = self.lr * (self.m[i] / denom);
            params[i] -= step;
        }
    }
};

test "sfd stabilizes zero gradient" {
    var gpa = std.heap.page_allocator;
    var sfd = try SFD.init(gpa, 4, 0.01);
    defer sfd.deinit();
    sfd.zero();
    var p = [_]f32{ 1, 2, 3, 4 };
    const g = [_]f32{ 0, 0, 0, 0 };
    sfd.update(p[0..], g[0..]);
    try std.testing.expect(p[0] == 1);
}
