    cap: abi.Cap,

    pub fn create(flags: u32) !Endpoint {
        var cap: abi.Cap = 0;
        const ec = abi.abi_ipc_create_endpoint(flags, &cap);
        if (!abi.ok(ec)) return error.IpcCreateFailed;
        return .{ .cap = cap };
    }

    pub fn send(self: *const Endpoint, data: []const u8, timeout_ns: u64) !void {
        const ec = abi.abi_ipc_send(self.cap, data.ptr, data.len, timeout_ns);
        if (!abi.ok(ec)) return error.IpcSendFailed;
    }

    pub fn recv(self: *const Endpoint, buf: []u8, timeout_ns: u64) !usize {
        var out_len: usize = 0;
        const ec = abi.abi_ipc_recv(self.cap, buf.ptr, buf.len, &out_len, timeout_ns);
        if (!abi.ok(ec)) return error.IpcRecvFailed;
        return out_len;
    }

    pub fn call(self: *const Endpoint, req: []const u8, resp: []u8, timeout_ns: u64) !usize {
        var out_len: usize = 0;
        const ec = abi.abi_ipc_call(self.cap, req.ptr, req.len, resp.ptr, &out_len, timeout_ns);
        if (!abi.ok(ec)) return error.IpcCallFailed;
        return out_len;
    }
