}

pub fn runPeriodic(task: fn (ctx: *anyopaque) void, ctx: *anyopaque, period_ns: u64, stop_flag: *volatile bool) void {
    while (!stop_flag.*) {
        const start = abi.abi_time_now();
        task(ctx);
        const end = abi.abi_time_now();
        const elapsed = if (end > start) end - start else 0;
        if (elapsed < period_ns) {
            // crude busy-wait/yield hybrid
            var remaining = period_ns - elapsed;
            while (remaining > 0) {
                yieldNow();
                const t = abi.abi_time_now();
                if (t - end >= remaining) break;
                remaining -= (t - end);
            }
        }
    }
}
