-- src/hw/rtl/RankerCore.hs
{-# LANGUAGE DataKinds, TypeApplications, ScopedTypeVariables #-}
module RankerCore where

import Clash.Prelude

-- Fixed-point helpers
type FX = SFixed 8 16

gelu :: FX -> FX
gelu x = 0.5 * x * (1 + tanh (s * (x + k * x*x*x)))
  where
    s = 0.7978845608
    k = 0.044715

-- Simple TF-IDF + positional decay scoring pipeline
-- Inputs are streams of (tf, idf, pos_decay, ent_density, sim) per segment
-- Outputs aggregated score
rankerStage :: (FX, FX, FX, FX, FX) -> FX
rankerStage (tf, idf, pos, ent, sim) =
  wtfidf * (tf * idf) + wpos * pos + went * ent + wsim * sim
  where
    wtfidf = 0.45
    wpos   = 0.25
    went   = 0.10
    wsim   = 0.20

topN :: forall n . (KnownNat n) => FX -> Vec n FX -> Vec n FX
topN x v = replace idx x v
  where
    (idx, _) = foldl (\(bi,bv) (i,val) -> if val < bv then (i,val) else (bi,bv))
                     (0, maxBound) (imap (,) v)

-- Pipelined core processing a stream
rankerCore
  :: HiddenClockResetEnable dom
  => Signal dom (FX, FX, FX, FX, FX)
  -> Signal dom FX
rankerCore = mealy step 0
  where
    step s inp =
      let y = rankerStage <$> inp
      in (s, fromJust y)
