-- Compute Hamming distance between two 64-bit words
hamming :: BitVector 64 -> BitVector 64 -> Unsigned 7
hamming a b = fromIntegral $ popCount (a `xor` b)

-- Sliding window nearest neighbor on a stream
ssiSearch
  :: HiddenClockResetEnable dom
  => Signal dom (BitVector 64) -- query simhash
  -> Signal dom (BitVector 64) -- candidate simhash
  -> Signal dom (Unsigned 64)  -- candidate offset
  -> Signal dom (Unsigned 7, Unsigned 64) -- (distance, offset)
ssiSearch q s off = bundle (d, off)
  where
    d = hamming <$> q <*> s
