let mix (x: u64) : u64 =
  let x1 = x ^ (x >> 33)
  let x2 = x1 * 0xff51afd7ed558ccdu64
  let x3 = x2 ^ (x2 >> 33)
  let x4 = x3 * 0xc4ceb9fe1a85ec53u64
  in x4 ^ (x4 >> 33)

entry simhash (tokens: []u32) : u64 =
  let bits = reduce (+) (replicate 64 0i32)
             (map (\t ->
                 let x = mix (u64 t * 0x9e3779b185ebca87u64)
                 in map (\i ->
                        if (x >> i) & 1u64 == 1u64 then 1i32 else -1i32)
                        (iota 64))
                  tokens)
  in reduce (\acc i -> acc | (if i.1 >= 0i32 then 1u64 << i.0 else 0u64))
            0u64 (zip (iota 64) bits)

entry conv2d_nchw (input: [][][ ][]f32, kernel: [][][ ][]f32,
                   stride_h: i64, stride_w: i64,
                   pad_h: i64, pad_w: i64) : [][][ ][]f32 =
  let n = length input
  let c = length (input[0])
  let h = length (input[0][0])
  let w = length (input[0][0][0])
  let f = length kernel
  let kh = length (kernel[0][0])
  let kw = length (kernel[0][0][0])
  let oh = (h + 2*pad_h - kh) / stride_h + 1
  let ow = (w + 2*pad_w - kw) / stride_w + 1
  in map (\nidx ->
       map (\fidx ->
         map (\ohidx ->
           map (\owidx ->
             let ihb = ohidx*stride_h - pad_h
             let iwb = owidx*stride_w - pad_w
             in reduce (+) 0.0f32
                (map (\cidx ->
                    reduce (+) 0.0f32
                      (map (\khidx ->
                        reduce (+) 0.0f32
                          (map (\kwidx ->
                            let ih = ihb + khidx
                            let iw = iwb + kwidx
                            in if ih >= 0 && ih < h && iw >= 0 && iw < w
                               then input[nidx][cidx][ih][iw] * kernel[fidx][cidx][khidx][kwidx]
                               else 0.0f32)
                          (iota kw)))
                      (iota kh)))
                (iota c)))
           (iota ow)))
       (iota f))
     (iota n)
