// src/zk/rsf_layer_proof.circom
pragma circom 2.1.6;

// RSF layer circuit: y1 = x1; y2 = x2 + W2 * gelu(W1 * x1 + b1) + b2
// Fixed small dimensions for proof-of-concept
template Linear(IN, OUT) {
    signal input x[IN];
    signal input W[OUT][IN];
    signal input b[OUT];
    signal output y[OUT];

    component muls[OUT][IN];
    signal sums[OUT];

    for (var o = 0; o < OUT; o++) {
        sums[o] <== b[o];
        for (var i = 0; i < IN; i++) {
            muls[o][i] = Multiplier();
            muls[o][i].a <== x[i];
            muls[o][i].b <== W[o][i];
            sums[o] <== sums[o] + muls[o][i].out;
        }
        y[o] <== sums[o];
    }
}

template GeLU(N) {
    signal input x[N];
    signal output y[N];
    // Polynomial approx: 0.5*x*(1 + tanh(0.79788456*(x + 0.044715*x^3)))
    // Use constraint-friendly cubic and tanh approximation via odd polynomial
    for (var i = 0; i < N; i++) {
        signal x2;
        signal x3;
        x2 <== x[i] * x[i];
        x3 <== x2 * x[i];

        // tanh(z) ~ z*(27 + z^2)/(27 + 9*z^2)
        signal z;
        z <== 0.79788456 * (x[i] + 0.044715 * x3);

        signal z2;
        z2 <== z * z;

        signal num;
        signal den;
        num <== z * (27 + z2);
        den <== 27 + 9 * z2;

        signal t; // approximate tanh
        // enforce t*den = num
        t * den === num;

        y[i] <== 0.5 * x[i] * (1 + t);
    }
}

template RSFLayer(H) {
    // D = 2H
    signal input x1[H];
    signal input x2[H];
    signal input W1[H][H];
    signal input b1[H];
    signal input W2[H][H];
    signal input b2[H];

    signal output y1[H];
    signal output y2[H];

    // y1 = x1
    for (var i = 0; i < H; i++) y1[i] <== x1[i];

    component lin1 = Linear(H, H);
    for (var i = 0; i < H; i++) {
        lin1.x[i] <== x1[i];
        lin1.b[i] <== b1[i];
        for (var j = 0; j < H; j++) lin1.W[i][j] <== W1[i][j];
    }

    component gelu = GeLU(H);
    for (var i = 0; i < H; i++) gelu.x[i] <== lin1.y[i];

    component lin2 = Linear(H, H);
    for (var i = 0; i < H; i++) {
        lin2.b[i] <== b2[i];
        for (var j = 0; j < H; j++) {
            lin2.W[i][j] <== W2[i][j];
        }
        lin2.x[i] <== gelu.y[i];
    }

    for (var i = 0; i < H; i++) {
        y2[i] <== x2[i] + lin2.y[i];
    }
}

// Simple multiplier gadget for clarity
template Multiplier() {
    signal input a;
    signal input b;
    signal output out;
    out <== a * b;
}

component main = RSFLayer(8);
