(* verification/isabelle/System_Security_Policy.thy *)
theory System_Security_Policy
  imports Main
begin

datatype proc = Tokenizer | Index | Ranker | Processor

datatype cap = CapIPC proc proc | CapMem proc | CapSched proc | CapDevice proc

record state =
  owns :: "proc ⇒ cap set"
  mem_write :: "proc ⇒ proc set"  (* who can write whose memory *)

definition dominates :: "proc ⇒ proc ⇒ bool" where
  "dominates a b ⟷ (a = Processor ∨ (a = Ranker ∧ b ≠ Processor) ∨ (a = Index ∧ b ∈ {Tokenizer, Index}) ∨ (a = Tokenizer ∧ b = Tokenizer))"

(* Bell-LaPadula no write up: low cannot write high *)
definition secure :: "state ⇒ bool" where
  "secure s ⟷ (∀p q. q ≠ p ⟶ (dominates q p ⟶ (q ∉ mem_write s p)))"

inductive step :: "state ⇒ state ⇒ bool" where
  GrantIPC: "⟦ c = CapIPC p q ⟧ ⟹ step s (s⦇owns := (owns s)(p := insert c (owns s p))⦈)" |
  RevokeIPC: "⟦ c = CapIPC p q ⟧ ⟹ step s (s⦇owns := (owns s)(p := (owns s p) - {c})⦈)" |
  MapMem: "⟦ c = CapMem p ⟧ ⟹ step s (s⦇mem_write := (mem_write s)(p := insert p (mem_write s p))⦈)" |
  ShareMem: "⟦ c = CapMem p ⟧ ⟹ step s (s⦇mem_write := (mem_write s)(q := insert p (mem_write s q))⦈)" |
  Sched: "⟦ c = CapSched p ⟧ ⟹ step s s" |
  Device: "⟦ c = CapDevice p ⟧ ⟹ step s s"

lemma dominates_refl: "dominates p p"
  unfolding dominates_def by auto

lemma dominates_proc:
  "dominates Processor p" "dominates Ranker Tokenizer" "¬ dominates Tokenizer Processor"
  unfolding dominates_def by auto

theorem secure_preserved:
  assumes "secure s" and "step s s'"
  shows "secure s'"
proof -
  from assms(2) show ?thesis
  proof cases
    case (GrantIPC c p q)
    then show ?thesis using assms(1) unfolding secure_def by auto
  next
    case (RevokeIPC c p q)
    then show ?thesis using assms(1) unfolding secure_def by auto
  next
    case (MapMem c p)
    hence "mem_write s' p = insert p (mem_write s p)" by auto
    then show ?thesis using assms(1) unfolding secure_def dominates_def by auto
  next
    case (ShareMem c p)
    hence upd: "mem_write s' = (mem_write s)(q := insert p (mem_write s q))" by auto
    show ?thesis
      unfolding secure_def
    proof (intro allI impI)
      fix x y :: proc
      assume "y ≠ x" and "dominates y x"
      thus "y ∉ mem_write s' x"
      proof -
        have casesxy: "y = Processor ∨ y = Ranker ∨ y = Index ∨ y = Tokenizer" by (cases y; auto)
        then show ?thesis
        proof
          assume "y = Processor"
          then show ?thesis using upd unfolding dominates_def by auto
        next
          assume "y = Ranker"
          then show ?thesis using upd unfolding dominates_def by auto
        next
          assume "y = Index"
          then show ?thesis using upd unfolding dominates_def by auto
        next
          assume "y = Tokenizer"
          then show ?thesis using upd unfolding dominates_def by auto
        qed
      qed
    qed
  next
    case (Sched c p)
    then show ?thesis using assms(1) unfolding secure_def by auto
  next
    case (Device c p)
    then show ?thesis using assms(1) unfolding secure_def by auto
  qed
qed

end
