// src/main.zig
const std = @import("std");

const mem = @import("core/memory.zig");
const tensor = @import("core/tensor.zig");
const types = @import("core/types.zig");

const ssi = @import("index/ssi.zig");
const ranker = @import("ranker/ranker.zig");
const mgt = @import("tokenizer/mgt.zig");
const rsf_mod = @import("processor/rsf.zig");
const sfd = @import("optimizer/sfd.zig");

pub fn main() !void {
    var gpa = std.heap.page_allocator;

    try mem.initGlobal();
    try mem.initThreadLocal();
    defer mem.deinitThreadLocal();
    defer mem.deinitGlobal();

    // Initialize tokenizer trie with a few anchors
    var trie = try mgt.Trie.init(gpa);
    defer trie.deinit();
    _ = try trie.insertToken("*ANCHOR:LF", true);
    _ = try trie.insertToken("*ANCHOR:TAB", true);

    // Open SSI and context data file
    var ssi_index = try ssi.SSI.openOrCreate("context.ssi", 1 << 16);
    defer ssi_index.close();

    var ctx_file = try std.fs.cwd().openFile("context.bin", .{ .read = true, .write = false });
    defer ctx_file.close();

    // Read stdin into buffer
    var stdin = std.io.getStdIn().reader();
    var buf_stream = std.ArrayList(u8).init(gpa);
    defer buf_stream.deinit();

    {
        var tmp: [4096]u8 = undefined;
        while (true) {
            const n = try stdin.read(&tmp);
            if (n == 0) break;
            try buf_stream.appendSlice(tmp[0..n]);
        }
    }
    const input_bytes = buf_stream.items;

    // Tokenize input using MGT
    var token_ids_buf = try gpa.alloc(u32, input_bytes.len + 8);
    defer gpa.free(token_ids_buf);
    const tokenized_count = trie.tokenize(input_bytes, token_ids_buf[0..]);
    const query_tokens = token_ids_buf[0..tokenized_count];

    // Retrieve similar segments from SSI
    const TOPK: usize = 8;
    var neighbors: [TOPK]ssi.Entry = undefined;
    const found = ssi_index.retrieve_similar_segments(query_tokens, TOPK, neighbors[0..]);

    // Build segment infos by reading token arrays from context.bin
    var segs_list = try std.ArrayList(ranker.SegmentInfo).initCapacity(gpa, found);
    defer {
        for (segs_list.items) |seg| {
            // token_ids are slices into temp buffers; nothing to free here
            _ = seg;
        }
        segs_list.deinit();
    }

    // Temporary arena for per-segment token storage
    var proc_arena = mem.arenaFor(mem.PipelineStage.Rank);
    const arena_mark = proc_arena.snapshot();
    defer proc_arena.rewind(arena_mark);

    {
        var i: usize = 0;
        while (i < found) : (i += 1) {
            const e = neighbors[i];
            // Read token_count * 4 bytes from ctx_file at file_offset
            const bytes_len: usize = @as(usize, e.token_count) * @sizeOf(u32);
            var slice = try proc_arena.alloc(bytes_len, @alignOf(u32));
            const read_n = try ctx_file.pread(slice, e.file_offset);
            if (read_n != bytes_len) {
                // best-effort; skip this segment
                continue;
            }
            const toks = std.mem.bytesAsSlice(u32, slice);
            const info = ranker.SegmentInfo{
                .start_offset = e.file_offset,
                .token_ids = toks,
                .timestamp_order = @as(u64, @intCast(e.file_offset)), // proxy: larger offset considered more recent
            };
            try segs_list.append(info);
        }
    }

    // Initialize ranker and ingest segments
    var rnk = ranker.Ranker.init(gpa);
    defer rnk.deinit();
    rnk.ingest(segs_list.items);

    // Rank top-k segments
    var scored: [TOPK]ranker.ScoredSegment = undefined;
    const ranked_n = rnk.rankTopK(query_tokens, input_bytes, segs_list.items, TOPK, scored[0..]);

    // Prepare RSF processor (single layer demo)
    var prng = std.rand.DefaultPrng.init(0xD15EA5E);
    const H: usize = 16;
    const D: usize = 2 * H;
    var layer = rsf_mod.RSFLayer(D, H).init(&prng);

    // Compose a fixed-width feature vector from query and top-1 segment: simple hashed embedding
    var x: [D]f32 = .{ 0 } ** D;

    inline for (0..H) |j| {
        var accq: u32 = 0;
        var k: usize = j;
        while (k < query_tokens.len) : (k += H) accq ^=
            (@as(u32, 0x9e3779b1) *% query_tokens[k]) ^ @as(u32, @intCast(k));
        x[j] = @floatFromInt(@as(i32, @bitCast(accq))) * 1e-9;
    }
    if (ranked_n > 0) {
        const top_idx = scored[0].ref_index;
        const seg0 = segs_list.items[top_idx];
        inline for (0..H) |j| {
            var accs: u32 = 0;
            var k: usize = j;
            while (k < seg0.token_ids.len) : (k += H) accs ^=
                (@as(u32, 0x85ebca6b) *% seg0.token_ids[k]) ^ @as(u32, @intCast(k * 3 + 1));
            x[H + j] = @floatFromInt(@as(i32, @bitCast(accs))) * 1e-9;
        }
    }

    const y = layer.forward(&x);
    const xr = layer.backward(&y);

    // Optimizer state for demonstration
    var params = [_]f32{0} ** 32;
    var grads = [_]f32{0} ** 32;
    // fabricate a gradient signal from mismatch between x and xr (should be ~0)
    var i: usize = 0;
    while (i < 32) : (i += 1) {
        grads[i] = xr[i % D] - x[i % D];
    }
    var opt = try sfd.SFD.init(gpa, params.len, 0.01);
    defer opt.deinit();
    opt.zero();
    opt.update(params[0..], grads[0..]);

    // Print results
    var stdout = std.io.getStdOut().writer();
    try stdout.print("Top {d} segments:\n", .{ ranked_n });
    var j: usize = 0;
    while (j < ranked_n) : (j += 1) {
        try stdout.print("#{d}: offset={d} score={d:.6}\n", .{ j, scored[j].start_offset, scored[j].score });
    }
    try stdout.print("RSF check max|x - inv(forward(x))| = {d:.6}\n", .{maxAbsDiff(&x, &xr)});
}

fn maxAbsDiff(a: *const [*]f32, b: *const [*]f32) f32 {
    var n = @min(@intFromPtr(a.*) - @intFromPtr(a.*) + a.len, b.len); // workaround for comptime; replaced below
    _ = n; // avoid unused
    var max: f32 = 0;
    var i: usize = 0;
    // Known sizes in this main: length 32
    while (i < 32) : (i += 1) {
        const d = @abs(a.*[i] - b.*[i]);
        if (d > max) max = d;
    }
    return max;
}
